const RARITY_WEIGHTS = { common: 50, uncommon: 25, rare: 15, legendary: 7, mythic: 3 };

const RARITY_EMOJI = {
  common: '⚪', uncommon: '🟢', rare: '🔵', legendary: '🟡', mythic: '🔴',
};

function getRandomPokemon() {
  const totalWeight = Object.values(RARITY_WEIGHTS).reduce((a, b) => a + b, 0);
  let roll = Math.random() * totalWeight;
  let selectedRarity = 'common';
  for (const [rarity, weight] of Object.entries(RARITY_WEIGHTS)) {
    roll -= weight;
    if (roll <= 0) { selectedRarity = rarity; break; }
  }
  const pool = POKEMON_LIST.filter(p => p.rarity === selectedRarity);
  return { ...pool[Math.floor(Math.random() * pool.length)] };
}

module.exports = { POKEMON_LIST, RARITY_WEIGHTS, RARITY_EMOJI, getRandomPokemon };
